" -m 20 http://127.0.0.1:3000/; echo "---TITLE---"; curl -s -m 20 http://127.0.0.1:3000/ | grep -io "<title>[^<]*</title>" | head -1; echo "---SIGNIN---"; curl -s -m 30 -X POST http://127.0.0.1:3000/api/v1/signin -H 'Content-Type: application/json' -d '{"username":"admin@example.com","password":"test"}' -w "
